(() => {
function render(){const g=window.gameDebug;if(!g)return;const s=g.state;document.getElementById('test-state').textContent=g.scene.name;document.getElementById('test-log').textContent=s.logs.at(-1);for(const[name,key]of[['light','lights'],['grid','grid'],['animations','animations']]){const b=document.getElementById('test-'+name);b.classList.toggle('enabled',s.settings[key]);b.setAttribute('aria-pressed',String(s.settings[key]));b.textContent=({light:'Динамический свет',grid:'Сетка пола',animations:'Анимации'})[name]+(s.settings[key]?' · вкл.':' · выкл.')}for(const n of['ambient','intensity']){document.getElementById(n).value=s.settings[n];document.getElementById(n+'-value').textContent=Math.round(s.settings[n]*100)+'%'}document.querySelectorAll('[data-test]').forEach(b=>b.disabled=g.busy)}
window.initTests=()=>{document.getElementById('start-trial').onclick=()=>window.Scenario.start();document.querySelectorAll('[data-test]').forEach(b=>b.onclick=()=>{const a=b.dataset.test;window.gameDebug.test(a,b.dataset.value);if(['scene','npc','dummies','fight','damage','crit','miss'].includes(a))window.viewsDebug.switchTab('map')});for(const n of['ambient','intensity'])document.getElementById(n).oninput=e=>window.gameDebug.test(n,e.target.value);render()};window.renderTests=render;
})();
